   421	
   422	        if (chr == '\n') {
   423	            emit(lexer, LEXEME_LINEFEED);
   424	            return lex_config;
   425	        }
   426	
   427	        if (isspace(chr)) {
   428	            ignore(lexer);
   429	            continue;
   430	        }
   431	
   432	        if (chr == '{') {
   433	            emit(lexer, LEXEME_OPEN_BRACKET);
   434	            return lex_config;
   435	        }
   436	
   437	        if (chr == '}') {
   438	            emit(lexer, LEXEME_CLOSE_BRACKET);
   439	            return lex_config;
   440	        }
   441	
   442	        if (chr == '=') {
   443	            emit(lexer, LEXEME_EQUAL);
   444	            return lex_config;
   445	        }
   446	
   447	        if (chr == '#')
   448	            return lex_comment;
   449	
   450	        if (chr == '\'' && !strncmp(lexer->pos, "''", 2))
   451	            return lex_multiline_string;
   452	        if (chr == '"' && !strncmp(lexer->pos, "\"\"", 2))
   453	            return lex_multiline_string;
   454	
   455	        if (chr == '$' && peek(lexer) == '{')
   456	            return lex_variable;
   457	
   458	        if (isstring(chr))
   459	            return lex_string;
   460	
   461	        return lex_error(lexer, "Invalid character");
   462	    }
   463	
   464	    emit(lexer, LEXEME_LINEFEED);
   465	    emit(lexer, LEXEME_EOF);
   466	
   467	    return NULL;
   468	}
